import assert from 'node:assert/strict';
import { matchRoute } from './router.mjs';
const routes = ['/users/:id', '/users/new', '/posts/:slug/comments/:cid'];
assert.deepEqual(matchRoute(routes, '/users/new'), { route: '/users/new', params: {} });
assert.deepEqual(matchRoute(routes, '/users/42'), { route: '/users/:id', params: { id: '42' } });
assert.deepEqual(matchRoute(routes, '/posts/hi/comments/7'), { route: '/posts/:slug/comments/:cid', params: { slug: 'hi', cid: '7' } });
assert.equal(matchRoute(routes, '/unknown'), null);
